\begin{lemma}
\label{lemma-cartan-eilenberg}
Let $\mathcal{A}$ be an abelian category with enough injectives.
Let $K^\bullet$ be a bounded below complex.
There exists a Cartan-Eilenberg resolution of $K^\bullet$.
\end{lemma}

\begin{lemma}
\label{lemma-smooth-omega-finite-locally-free}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is smooth.
Then the module of differentials $\Omega_{X/S}$ of $X$ over $S$
is finite locally free and
$$
\text{rank}_x(\Omega_{X/S}) = \dim_x(X_{f(x)})
$$
for every $x \in X$.
\end{lemma}

\begin{proof}
The statement is local on $X$ and $S$.
By Lemma \ref{lemma-smooth-locally-standard-smooth}
above we may assume that $f$ is a standard smooth morphism of affines.
In this case the result follows from
Algebra, Lemma \ref{algebra-lemma-standard-smooth}
(and the definition of a relative global complete intersection, see
Algebra,
Definition \ref{algebra-definition-relative-global-complete-intersection}).
\end{proof}

\begin{lemma}
\label{lemma-kunneth-special}
In the situation above the cup product (\ref{equation-de-rham-kunneth})
is an isomorphism in $D(A)$ if the following assumptions hold
\begin{enumerate}
\item $S = \Spec(A)$ is affine,
\item $X$ and $Y$ are quasi-compact with affine diagonal,
\item $\mathcal{F}^\bullet$ is bounded,
\item $\mathcal{G}^\bullet$ is bounded below,
\item $\mathcal{F}^n$ is $S$-flat, and
\item $\mathcal{G}^m$ is $S$-flat.
\end{enumerate}
\end{lemma}
